using System;
using System.Text.Json.Serialization;

namespace Adyen.Models;

/// <summary>
/// The details of the payment. You must show your user these details before they confirm or cancel the payment.
/// </summary>
public record PaymentDetails1
{
    [JsonPropertyName("amount")]
    public required Amount Amount { get; init; }

    [JsonPropertyName("counterparty")]
    public required Counterparty Counterparty { get; init; }

    /// <summary>
    /// The description for the payment. It is generated by the payment method, such as iDEAL, and should be shown to the user.
    /// </summary>
    [JsonPropertyName("description")]
    public required string Description { get; init; }

    /// <summary>
    /// The expiration date of the payment in ISO DateTime format, as described on ISO 20022 (YYYY-MM-DDThh:mm:ss.sss+/-hh:mm).
    /// <para>
    /// Example: <b>2025-12-30T14:15:30+01:00</b>
    /// </para>
    /// </summary>
    [JsonPropertyName("expiresAt")]
    public required DateTimeOffset ExpiresAt { get; init; }
}
